import { BaseSelectList, SelectStyle, LabelChangeProps, SelectListProps } from './base';

export const SelectList = <T,>({
  options,
  selectedOption,
  valueKey,
  defaultSelectedOption,
  onSelect,
  selectStyle = SelectStyle.DEFAULT,
}: SelectListProps<T>) => {
  const handleRadioChange = ({ option }: LabelChangeProps<T>) => {
    //console.log('option', option);
    onSelect(option);
  };

  return (
    <div className="select-list">
      <BaseSelectList
        options={options}
        selectedOption={selectedOption}
        valueKey={valueKey}
        defaultSelectedOption={defaultSelectedOption}
        onLabelChange={handleRadioChange}
        selectStyle={selectStyle}
        maxHeight="auto"
        className={'pt-5'}
      />
    </div>
  );
};
